use std::fs::File;
use std::io::{self, Read};
pub fn vtx_read_packet_id(f: &mut File) -> io::Result<u16> {
    let mut buf = [0u8; 4096];
    f.read_exact(&mut buf[..2])?;
    Ok(u16::from_be_bytes([buf[0], buf[1]]))
}
